3	actor LocalMetadataEngine {
4	    private let store: any LocalThreadMetadataStoring
5	    private let now: @Sendable () -> Date
6	    private var values: [LocalThreadMetadataKey: LocalThreadMetadata]
7	
8	    init(
9	        store: any LocalThreadMetadataStoring,
10	        initialValues: [LocalThreadMetadataKey: LocalThreadMetadata] = [:],
11	        now: @escaping @Sendable () -> Date = Date.init
12	    ) {
13	        self.store = store
14	        self.values = initialValues
15	        self.now = now
16	    }
17	
18	    func load() async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
19	        values = try await store.load()
20	        return values
21	    }
22	
23	    func replace(_ values: [LocalThreadMetadataKey: LocalThreadMetadata]) {
24	        self.values = values
25	    }
26	
27	    func migrateHostAliases(
28	        using resolver: DockHostIdentityResolver
29	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
30	        var changed = false
31	        var nextValues: [LocalThreadMetadataKey: LocalThreadMetadata] = [:]
32	        let entries = values.sorted { lhs, rhs in
33	            let lhsKey = [lhs.key.hostID, lhs.key.backendSessionID, lhs.key.threadID].joined(separator: "\u{1f}")
34	            let rhsKey = [rhs.key.hostID, rhs.key.backendSessionID, rhs.key.threadID].joined(separator: "\u{1f}")
35	            return lhsKey < rhsKey
36	        }
37	
38	        for (key, metadata) in entries {
39	            let logicalHostID = resolver.migrationLogicalHostID(forAlias: key.hostID) ?? key.hostID
40	            let nextKey = LocalThreadMetadataKey(
41	                hostID: logicalHostID,
42	                backendSessionID: key.backendSessionID,
43	                threadID: key.threadID
44	            )
45	            changed = changed || nextKey != key
46	            if let existing = nextValues[nextKey] {
47	                nextValues[nextKey] = key == nextKey
48	                    ? Self.mergedMetadata(metadata, existing)
49	                    : Self.mergedMetadata(existing, metadata)
50	                changed = true
51	            } else {
52	                nextValues[nextKey] = metadata
53	            }
54	        }
55	
56	        let normalizedValues = PinnedMetadataOrdering.normalized(nextValues)
57	        guard changed || normalizedValues != values else {
58	            values = normalizedValues
59	            return normalizedValues
60	        }
61	        values = try await store.save(normalizedValues)
62	        return values
63	    }
64	
65	    func setLabel(
66	        _ label: String?,
67	        for key: LocalThreadMetadataKey
68	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
69	        var metadata = values[key] ?? LocalThreadMetadata()
70	        metadata.label = label
71	        return try await save(metadata: metadata, for: key)
72	    }
73	
74	    func setRail(
75	        _ rail: DockRowRail?,
76	        for key: LocalThreadMetadataKey
77	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
78	        var metadata = values[key] ?? LocalThreadMetadata()
79	        metadata.rail = rail
80	        return try await save(metadata: metadata, for: key)
81	    }
82	
83	    func setPinned(
84	        _ isPinned: Bool,
85	        for row: DockRowViewModel
86	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
87	        let key = row.metadataKey
88	        var nextValues = PinnedMetadataOrdering.normalized(values)
89	        var metadata = nextValues[key] ?? LocalThreadMetadata()
90	        if isPinned {
91	            let wasPinned = metadata.isPinned
92	            metadata.isPinned = true
93	            metadata.pinnedAt = metadata.pinnedAt ?? now()
94	            if !wasPinned || metadata.pinnedOrder == nil {
95	                metadata.pinnedOrder = PinnedMetadataOrdering.nextOrder(in: nextValues, excluding: key)
96	            }
97	            metadata.lastKnownPinnedDisplay = LocalPinnedDisplaySnapshot(row: row)
98	        } else {
99	            metadata.isPinned = false
100	            metadata.pinnedAt = nil
101	            metadata.pinnedOrder = nil
102	            metadata.lastKnownPinnedDisplay = nil
103	        }
104	        nextValues[key] = metadata
105	        return try await save(metadataValues: PinnedMetadataOrdering.normalized(nextValues))
106	    }
107	
108	    func reorderPinnedRows(
109	        _ visibleRowsInNewOrder: [DockRowViewModel]
110	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
111	        var nextValues = PinnedMetadataOrdering.normalized(values)
112	        let visibleKeys = PinnedMetadataOrdering.uniqueKeys(
113	            visibleRowsInNewOrder.map(\.metadataKey).filter { nextValues[$0]?.isPinned == true }
114	        )
115	        guard visibleKeys.count > 1 else {
116	            return nextValues
117	        }
118	
119	        let visibleKeySet = Set(visibleKeys)
120	        let orderedPinnedKeys = PinnedMetadataOrdering.orderedKeys(in: nextValues)
121	        var reorderedVisibleKeys = visibleKeys.makeIterator()
122	        let mergedKeys = orderedPinnedKeys.compactMap { key in
123	            if visibleKeySet.contains(key) {
124	                return reorderedVisibleKeys.next()
125	            }
126	            return key
127	        }
128	
129	        for (index, key) in mergedKeys.enumerated() {
130	            guard var metadata = nextValues[key], metadata.isPinned else {
131	                continue
132	            }
133	            metadata.pinnedOrder = index
134	            nextValues[key] = metadata
135	        }
136	        return try await save(metadataValues: nextValues)
137	    }
138	
139	    private func save(
140	        metadata: LocalThreadMetadata,
141	        for key: LocalThreadMetadataKey
142	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
143	        values = try await store.save(metadata.isEmpty ? nil : metadata, for: key)
144	        return values
145	    }
146	
147	    private func save(
148	        metadataValues nextValues: [LocalThreadMetadataKey: LocalThreadMetadata]
149	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
150	        let persistedValues = nextValues.filter { !$0.value.isEmpty }
151	        guard values != persistedValues else {
152	            return values
153	        }
154	        values = try await store.save(persistedValues)
155	        return values
156	    }
157	
158	    private static func mergedMetadata(
159	        _ current: LocalThreadMetadata,
160	        _ incoming: LocalThreadMetadata
161	    ) -> LocalThreadMetadata {
162	        var result = current
163	        if result.label == nil {
164	            result.label = incoming.label
165	        }
166	        if result.rail == nil {
167	            result.rail = incoming.rail
168	        }
169	        guard incoming.isPinned else {
170	            return result
171	        }
172	
173	        result.isPinned = true
174	        if let incomingPinnedAt = incoming.pinnedAt {
175	            if let currentPinnedAt = result.pinnedAt {
176	                result.pinnedAt = min(currentPinnedAt, incomingPinnedAt)
177	            } else {
178	                result.pinnedAt = incomingPinnedAt
179	            }
180	        }
181	        if let incomingPinnedOrder = incoming.pinnedOrder {
182	            if let currentPinnedOrder = result.pinnedOrder {
183	                result.pinnedOrder = min(currentPinnedOrder, incomingPinnedOrder)
184	            } else {
185	                result.pinnedOrder = incomingPinnedOrder
186	            }
187	        }
188	        if result.lastKnownPinnedDisplay == nil {
189	            result.lastKnownPinnedDisplay = incoming.lastKnownPinnedDisplay
190	        }
191	        return result
192	    }
193	}
