19	struct DockCardProjection: Equatable, Sendable {
20	    let lens: DockLensID
21	    let pinnedRows: [DockRowViewModel]
22	    let allPinnedRows: [DockRowViewModel]
23	    let pinnedSummary: DockPinnedSummary
24	    let rows: [DockRowViewModel]
25	    let groups: [DockProjectionGroupViewModel]
26	    let summary: DockProjectionSummary
27	    let hiddenCounts: DockProjectionHiddenCounts
28	    let availableFacets: DockProjectionFacets
29	    let emptyReason: DockProjectionEmptyReason?
30	    let isPartial: Bool
31	    let checkingHostCount: Int
32	}
33	
34	extension DockSnapshot {
35	    func project(options: DockProjectionOptions) -> DockCardProjection {
36	        DockCardProjectionProjector(snapshot: self, options: options).project()
37	    }
38	}
