40	private struct DockCardProjectionProjector {
41	    let snapshot: DockSnapshot
42	    let options: DockProjectionOptions
43	
44	    func project() -> DockCardProjection {
45	        let searchedRows = snapshot.rows.filter(matchesSearch)
46	        let filteredIgnoringIdle = searchedRows.filter(matchesNonIdleFilters)
47	        let pinnedRows = filteredIgnoringIdle.filter(\.isPinned).sorted(by: pinnedRowPrecedes)
48	        let hiddenIdleRows = options.filters.showsIdle
49	            ? []
50	            : filteredIgnoringIdle.filter { !$0.isPinned && $0.status == .idle }
51	        let hiddenIdleCount = hiddenIdleRows.count
52	        let bodyRows = filteredIgnoringIdle
53	            .filter { !$0.isPinned }
54	            .filter { options.filters.showsIdle || $0.status != .idle }
55	            .sorted(by: rowPrecedesByRecency)
56	        let visibleRows = (pinnedRows + bodyRows).sorted(by: rowPrecedesByRecency)
57	        let allPinnedRows = snapshot.rows.filter(\.isPinned).sorted(by: pinnedRowPrecedes)
58	        let groups = groups(for: bodyRows, hiddenIdleRows: hiddenIdleRows)
59	        let emptyReason = visibleRows.isEmpty ? emptyReason(searchedRows: searchedRows, hiddenIdleCount: hiddenIdleCount) : nil
60	
61	        return DockCardProjection(
62	            lens: options.lens,
63	            pinnedRows: pinnedRows,
64	            allPinnedRows: allPinnedRows,
65	            pinnedSummary: DockPinnedSummary(
66	                visibleCount: pinnedRows.count,
67	                totalCount: allPinnedRows.count,
68	                hiddenByScopeCount: max(0, allPinnedRows.count - pinnedRows.count)
69	            ),
70	            rows: options.lens == .newest ? bodyRows : [],
71	            groups: groups,
72	            summary: summary(for: visibleRows),
73	            hiddenCounts: DockProjectionHiddenCounts(idle: hiddenIdleCount),
74	            availableFacets: availableFacets(),
75	            emptyReason: emptyReason,
76	            isPartial: snapshot.isPartial,
77	            checkingHostCount: snapshot.hostStates.filter { $0.status == .checking }.count
78	        )
79	    }
80	
81	    private func groups(
82	        for rows: [DockRowViewModel],
83	        hiddenIdleRows: [DockRowViewModel]
84	    ) -> [DockProjectionGroupViewModel] {
85	        switch options.lens {
86	        case .newest:
87	            return []
88	        case .host:
89	            return hostGroups(for: rows, hiddenIdleRows: hiddenIdleRows)
90	        case .branch:
91	            return branchGroups(for: rows, hiddenIdleRows: hiddenIdleRows)
92	        }
93	    }
94	
95	    private func hostGroups(
96	        for rows: [DockRowViewModel],
97	        hiddenIdleRows: [DockRowViewModel]
98	    ) -> [DockProjectionGroupViewModel] {
99	        let stateByHost = Dictionary(uniqueKeysWithValues: snapshot.hostStates.map { ($0.host.id, $0) })
100	        return snapshot.hosts.compactMap { host in
101	            if !options.filters.selectedHostIDs.isEmpty,
102	               !options.filters.selectedHostIDs.contains(host.id) {
103	                return nil
104	            }
105	
106	            let hostRows = rows
107	                .filter { rowBelongs($0, to: host.id) }
108	                .sorted(by: rowPrecedesByRecency)
109	            let hiddenIdleCount = hiddenIdleRows.filter { rowBelongs($0, to: host.id) }.count
110	            let hostState = stateByHost[host.id]
111	            let isUnavailable = hostState?.status.isUnavailable ?? false
112	            guard !hostRows.isEmpty || hiddenIdleCount > 0 || isUnavailable || hostState?.status == .checking else {
113	                return nil
114	            }
115	
116	            return DockProjectionGroupViewModel(
117	                id: "host::\(host.id)",
118	                kind: .host,
119	                title: host.displayName,
120	                subtitle: hostState?.status.subtitle ?? "\(hostRows.count) sessions",
121	                rows: hostRows,
122	                hostIDs: [host.id],
123	                newestActivityDate: hostRows.map(\.lastActivityDate).max(),
124	                runningCount: hostRows.filter { $0.status == .running }.count,
125	                hiddenIdleCount: hiddenIdleCount,
126	                isUnavailable: isUnavailable,
127	                unavailableMessage: hostState?.status.unavailableMessage
128	            )
129	        }
130	        .sorted(by: groupPrecedes)
131	    }
132	
133	    private func branchGroups(
134	        for rows: [DockRowViewModel],
135	        hiddenIdleRows: [DockRowViewModel]
136	    ) -> [DockProjectionGroupViewModel] {
137	        let groupedRows = Dictionary(grouping: rows, by: \.branch)
138	        let hiddenIdleCountsByBranch = Dictionary(grouping: hiddenIdleRows, by: \.branch)
139	            .mapValues(\.count)
140	        return groupedRows.map { branch, rows in
141	            let sortedRows = rows.sorted(by: rowPrecedesByRecency)
142	            let hostNames = Set(sortedRows.map(\.hostDisplayName)).sorted()
143	            return DockProjectionGroupViewModel(
144	                id: "branch::\(branch)",
145	                kind: .branch,
146	                title: branch,
147	                subtitle: "\(sortedRows.count) sessions · \(hostNames.joined(separator: ", "))",
148	                rows: sortedRows,
149	                hostIDs: Set(sortedRows.map(hostIDForGroup)).sorted(),
150	                newestActivityDate: sortedRows.map(\.lastActivityDate).max(),
151	                runningCount: sortedRows.filter { $0.status == .running }.count,
152	                hiddenIdleCount: hiddenIdleCountsByBranch[branch] ?? 0,
153	                isUnavailable: false,
154	                unavailableMessage: nil
