167	        parts.append(options.filters.showsIdle ? "Idle shown" : "Idle hidden")
168	
169	        let query = normalizedQuery(options.searchText)
170	        if !query.isEmpty {
171	            parts.append("Search: \(query)")
172	        }
173	        if snapshot.isPartial {
174	            parts.append("Partial")
175	        }
176	
177	        return DockProjectionSummary(
178	            text: parts.joined(separator: " · "),
179	            activeFilterCount: options.filters.activeFilterCount + (query.isEmpty ? 0 : 1),
180	            resultCount: rows.count
