186	            return "Hosts: Any"
187	        }
188	        if options.filters.selectedHostIDs.count == 1,
189	           let hostID = options.filters.selectedHostIDs.first {
190	            return "Host: \(hostName(for: hostID))"
191	        }
192	        return "Hosts: \(options.filters.selectedHostIDs.count)"
193	    }
