195	    private var branchSummaryText: String {
196	        guard !options.filters.selectedBranches.isEmpty else {
197	            return "Branches: Any"
198	        }
199	        if options.filters.selectedBranches.count == 1,
200	           let branch = options.filters.selectedBranches.first {
201	            return "Branch: \(branch)"
202	        }
203	        return "Branches: \(options.filters.selectedBranches.count)"
204	    }
