207	        let allStatuses = Set(DockRowStatusKind.allCases)
208	        guard options.filters.statusKinds != allStatuses else {
209	            return "Status: Any"
210	        }
211	        if options.filters.statusKinds.count == 1,
212	           let status = options.filters.statusKinds.first {
213	            return "Status: \(status.label)"
214	        }
215	        return "Statuses: \(options.filters.statusKinds.count)"
216	    }
