220	        let selectedCount = options.filters.selectedRepositories.count
221	        if selectedCount == 0, query.isEmpty {
222	            return "Repo: Any"
223	        }
224	        if selectedCount == 1,
225	           query.isEmpty,
226	           let repository = options.filters.selectedRepositories.first {
227	            return "Repo: \(repository)"
228	        }
229	        if selectedCount == 0 {
