242	            statuses: DockRowStatusKind.allCases.filter { status in
243	                snapshot.rows.contains { $0.status == status }
244	            },
245	            repositories: uniqueSorted(snapshot.rows.map(\.repository)),
246	            sources: DockSourceFilter.allCases.filter { source in
247	                source == .any || snapshot.rows.contains { source.includes($0.origin) }
