256	    private func emptyReason(
257	        searchedRows: [DockRowViewModel],
258	        hiddenIdleCount: Int
259	    ) -> DockProjectionEmptyReason {
260	        if snapshot.rows.isEmpty {
261	            return .noData
262	        }
263	        if hiddenIdleCount > 0 {
264	            return .idleHidden
265	        }
266	        if !normalizedQuery(options.searchText).isEmpty, searchedRows.isEmpty {
267	            return .noSearchMatches
268	        }
269	        if selectedHostsAreUnavailable {
270	            return .hostUnavailable
271	        }
272	        return .noFilterMatches
273	    }
