275	    private var selectedHostsAreUnavailable: Bool {
276	        guard !options.filters.selectedHostIDs.isEmpty else {
277	            return false
278	        }
279	        let states = snapshot.hostStates.filter { options.filters.selectedHostIDs.contains($0.host.id) }
280	        return !states.isEmpty && states.allSatisfy(\.status.isUnavailable)
