283	    private func matchesNonIdleFilters(_ row: DockRowViewModel) -> Bool {
284	        if !options.filters.selectedHostIDs.isEmpty,
285	           !options.filters.selectedHostIDs.contains(where: { selectedHostID in
286	               rowBelongs(row, to: selectedHostID)
287	           }) {
288	            return false
289	        }
290	        if !options.filters.selectedBranches.isEmpty,
291	           !options.filters.selectedBranches.contains(where: { selected in
292	               row.branch.compare(selected, options: [.caseInsensitive, .diacriticInsensitive]) == .orderedSame
293	           }) {
294	            return false
295	        }
296	        if !options.filters.statusKinds.contains(row.status) {
297	            return false
298	        }
299	        if !options.filters.selectedRepositories.isEmpty,
300	           !options.filters.selectedRepositories.contains(row.repository) {
301	            return false
302	        }
303	        let repositoryQuery = normalizedQuery(options.filters.repositoryQuery)
304	        if !repositoryQuery.isEmpty,
305	           !row.repository.localizedCaseInsensitiveContains(repositoryQuery) {
306	            return false
307	        }
308	        return options.filters.source.includes(row.origin)
309	    }
