311	    private func rowBelongs(_ row: DockRowViewModel, to configuredHostID: String) -> Bool {
312	        snapshot.hostIdentityResolver.contains(
313	            rowHostID: row.id.hostID,
314	            sourceConfiguredHostID: row.sourceHostID,
315	            in: configuredHostID
316	        )
317	            || row.sourceHostID == configuredHostID
318	    }
