320	    private func hostIDForGroup(_ row: DockRowViewModel) -> String {
321	        snapshot.hostIdentityResolver.resolve(
322	            rowHostID: row.id.hostID,
323	            sourceConfiguredHostID: row.sourceHostID
324	        )?.host.id
325	            ?? row.sourceHostID
326	            ?? row.id.hostID
327	    }
328	
329	    private func matchesSearch(_ row: DockRowViewModel) -> Bool {
330	        let query = normalizedQuery(options.searchText)
331	        guard !query.isEmpty else {
332	            return true
333	        }
334	
335	        return searchableValues(for: row).contains { value in
336	            value.localizedCaseInsensitiveContains(query)
337	        }
338	    }
339	
340	    private func searchableValues(for row: DockRowViewModel) -> [String] {
341	        [
342	            row.title,
343	            row.hostDisplayName,
344	            row.id.hostID,
345	            row.repository,
346	            row.branch,
347	            row.summary,
348	            row.status.label,
349	            row.label,
350	            row.origin.automationKind,
351	            row.id.threadID
352	        ].compactMap { $0 }
353	    }
354	
355	    private func groupPrecedes(_ lhs: DockProjectionGroupViewModel, _ rhs: DockProjectionGroupViewModel) -> Bool {
356	        let lhsDate = lhs.newestActivityDate ?? Date.distantPast
357	        let rhsDate = rhs.newestActivityDate ?? Date.distantPast
358	        if lhsDate != rhsDate {
359	            return lhsDate > rhsDate
360	        }
361	
362	        let titleOrder = lhs.title.localizedCaseInsensitiveCompare(rhs.title)
363	        if titleOrder != .orderedSame {
364	            return titleOrder == .orderedAscending
365	        }
366	        return lhs.id < rhs.id
367	    }
368	
369	    private func rowPrecedesByRecency(_ lhs: DockRowViewModel, _ rhs: DockRowViewModel) -> Bool {
370	        // Global "Newest" must be based on real activity time. Relay order keys are
371	        // only stable inside one host's stream, so using them first can interleave
372	        // stale rows from another host above newer work.
373	        if lhs.lastActivityDate != rhs.lastActivityDate {
374	            return lhs.lastActivityDate > rhs.lastActivityDate
375	        }
376	
377	        if let lhsOrderKey = lhs.orderKey,
378	           let rhsOrderKey = rhs.orderKey,
379	           lhsOrderKey != rhsOrderKey {
380	            return lhsOrderKey < rhsOrderKey
381	        }
382	
383	        let titleOrder = lhs.title.localizedCaseInsensitiveCompare(rhs.title)
384	        if titleOrder != .orderedSame {
385	            return titleOrder == .orderedAscending
386	        }
387	
388	        return "\(lhs.id.hostID)::\(lhs.id.threadID)" < "\(rhs.id.hostID)::\(rhs.id.threadID)"
389	    }
390	
391	    private func pinnedRowPrecedes(_ lhs: DockRowViewModel, _ rhs: DockRowViewModel) -> Bool {
392	        if let lhsOrder = lhs.pinnedOrder,
393	           let rhsOrder = rhs.pinnedOrder,
394	           lhsOrder != rhsOrder {
395	            return lhsOrder < rhsOrder
396	        }
397	        if lhs.pinnedOrder != nil {
398	            return true
399	        }
400	        if rhs.pinnedOrder != nil {
401	            return false
402	        }
403	
404	        let lhsPinnedAt = lhs.pinnedAt ?? Date.distantPast
405	        let rhsPinnedAt = rhs.pinnedAt ?? Date.distantPast
406	        if lhsPinnedAt != rhsPinnedAt {
407	            return lhsPinnedAt < rhsPinnedAt
408	        }
409	
410	        return "\(lhs.id.hostID)::\(lhs.id.threadID)" < "\(rhs.id.hostID)::\(rhs.id.threadID)"
411	    }
412	
413	    private func normalizedQuery(_ value: String) -> String {
414	        value.trimmingCharacters(in: .whitespacesAndNewlines)
415	    }
416	
417	    private func uniqueSorted(_ values: [String]) -> [String] {
418	        Set(values).sorted { lhs, rhs in
419	            lhs.localizedCaseInsensitiveCompare(rhs) == .orderedAscending
420	        }
421	    }
422	}
